<script>
(()=>{const form=document.getElementById('announcement-form'),editor=document.getElementById('announcement-editor'),content=document.getElementById('announcement-content'),dialog=document.getElementById('announcement-preview'),card=document.getElementById('preview-card');const sync=()=>content.value=editor.innerHTML;editor.addEventListener('input',sync);editor.addEventListener('paste',event=>{event.preventDefault();document.execCommand('insertText',false,event.clipboardData.getData('text/plain'));sync();});form.addEventListener('submit',sync);
 document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{editor.focus();document.execCommand(b.dataset.format,false);sync();});document.getElementById('editor-link').onclick=()=>{const url=prompt('HTTPS link or local /path');if(url&&(/^(https?:\/\/|\/(?!\/))/.test(url))&&!/[\x00-\x20\\]/.test(url)){editor.focus();document.execCommand('createLink',false,url);sync();}};document.getElementById('editor-color').oninput=e=>{editor.focus();document.execCommand('foreColor',false,e.target.value);sync();};
 const audienceOptions=()=>document.getElementById('member-group-option').hidden=form.audience.value!=='group';audienceOptions();form.audience.addEventListener('change',audienceOptions);form.type.addEventListener('change',()=>{if(['photo','combined'].includes(form.type.value))document.getElementById('photo-options').open=true;});form.addEventListener('invalid',e=>{e.target.closest('details')?.setAttribute('open','');},true);
 let imageUrl=null;document.getElementById('announcement-image').onchange=e=>{if(imageUrl)URL.revokeObjectURL(imageUrl);imageUrl=e.target.files[0]?URL.createObjectURL(e.target.files[0]):null;};
 // Preview uses a DOM allowlist; raw pasted markup never enters the preview document.
 const clean=node=>{if(node.nodeType===Node.TEXT_NODE)return document.createTextNode(node.textContent);if(node.nodeType!==Node.ELEMENT_NODE)return document.createTextNode('');const tag=node.tagName.toLowerCase();if(['script','style','svg','math','iframe','object'].includes(tag))return document.createTextNode('');const el=document.createElement(['p','br','b','strong','i','em','u','ul','ol','li','a','span','div','font'].includes(tag)?(tag==='font'?'span':tag):'span');if(tag==='a'){const url=node.getAttribute('href')||'';if(/^(https?:\/\/|\/(?!\/))/.test(url)&&!/[\x00-\x20\\]/.test(url))el.href=url;}if(['left','center','right'].includes(node.style.textAlign))el.style.textAlign=node.style.textAlign;el.style.color=node.style.color||'';[...node.childNodes].forEach(c=>el.append(clean(c)));return el;};
 document.getElementById('preview-open').onclick=()=>{card.replaceChildren();const title=document.createElement('h2');title.textContent=form.heading.value||form.title.value;card.append(title);const sub=document.createElement('p');sub.textContent=form.subheading.value;card.append(sub);const existing=form.querySelector('img');const src=imageUrl||(!form.remove_image?.checked?existing?.src:null);if(src){const img=document.createElement('img');img.src=src;img.alt=form.image_alt.value;card.append(img);}const doc=new DOMParser().parseFromString(editor.innerHTML,'text/html');[...doc.body.childNodes].forEach(n=>card.append(clean(n)));if(form.button_text.value){const b=document.createElement('button');b.type='button';b.textContent=form.button_text.value;card.append(b);}document.getElementById('preview-position').textContent=form.position.selectedOptions[0].text+' · '+form.audience.selectedOptions[0].text;card.style.marginLeft=['corner'].includes(form.position.value)?'auto':'';card.style.marginRight=['corner'].includes(form.position.value)?'0':'';card.style.borderRadius=['top','bottom','banner','ticker'].includes(form.position.value)?'0':'15px';dialog.showModal();};document.getElementById('preview-close').onclick=()=>dialog.close();document.getElementById('preview-mobile').onclick=()=>card.classList.add('mobile');document.getElementById('preview-desktop').onclick=()=>card.classList.remove('mobile');
})();
</script></body></html>
